bugRepair.brokenCode:
.btn {
  transition: all 0.3;
  /* النتيجة: لا يحدث أي انتقال ناعم وتتغير الألوان لحظياً بقفزة حادة! */
}

@keyframes spin {
  to { transform: rotate(360deg); }
}
.loader {
  animation: spin 1 infinite;
}

bugRepair.fixedCode:
@keyframes spin {
  to { transform: rotate(360deg); }
}
.loader {
  animation: spin 1s infinite linear;
}

bugRepair.brokenCode:
.tooltip-btn::after {
  content: attr(title);
  position: absolute;
  /* المشكلة: المتصفح يظهر تلميح النظام الأصفر الافتراضي أيضاً فيحدث ازدواج قبيح */
}

img.responsive {
  width: 100%;
  height: 200px;
  /* النتيجة: تمطط الصورة وتشوه ملامح الوجوه بداخلها! */
}

.modal-backdrop {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  /* المشكلة: عند تمرير الصفحة تبتعد طبقة التعتيم وتنكشف الصفحة خلفها */
}

bugRepair.fixedCode:
.modal-backdrop {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}
